// spec: specs/ssr-seo-public.md (2.5)
// seed: tests/seed.spec.ts
// Прод, только чтение: все объявления из sitemap, сырой HTML через request API, параллельно по 8.
// Дополняет listing-jsonld (#fbeedf: один BreadcrumbList/один блок, нет контактов, нет пустых полей) — здесь тип по цене и связь с SSR-блоком.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, meta, jsonLd, nodesOfType, listingNode, typesOf, rootHtml, seoBody, labeled, pool } from './ssr-seo.helpers';

function hasKeyDeep(v: unknown, key: string): boolean {
  if (Array.isArray(v)) return v.some((x) => hasKeyDeep(x, key));
  if (v && typeof v === 'object') return Object.entries(v).some(([k, x]) => k === key || hasKeyDeep(x, key));
  return false;
}

test.describe('SSR и SEO публичных страниц — метаданные', () => {
  test('Объявления: twitter:card summary_large_image, валидный JSON-LD с BreadcrumbList; с ценой — Product с offers ILS, без цены — Offer #b489db @desktop @prod-safe', async ({ request }) => {
    test.setTimeout(10 * 60_000);
    const sm = await readSitemap(request);
    expect(sm.listingIds.length, 'объявления в sitemap').toBeGreaterThan(0);

    const rows = await pool(
      sm.listingIds,
      async (id) => {
        const problems: string[] = [];
        const { status, html } = await rawHtml(request, `/businessdetail?id=${id}`);
        if (status !== 200) return { id, problems: [`HTTP ${status}`], priced: false };
        if (meta(html, 'twitter:card') !== 'summary_large_image') problems.push(`twitter:card=${meta(html, 'twitter:card')}`);

        const ld = jsonLd(html);
        if (ld.errors.length) problems.push(`JSON-LD не парсится: ${ld.errors.join('; ')}`);
        if (nodesOfType(ld, 'BreadcrumbList').length === 0) problems.push('нет BreadcrumbList');
        const node = listingNode(ld);
        const ssrPrice = labeled(seoBody(rootHtml(html) ?? '')?.html ?? '', 'מחיר מבוקש:');
        const priced = !!node && hasKeyDeep(node, 'price');
        if (!node) {
          problems.push('нет блока Product/Offer');
        } else if (typesOf(node).includes('Product')) {
          const offers = [node['offers']].flat()[0] as Record<string, unknown> | undefined;
          const price = Number(String(offers?.['price'] ?? '').replace(/,/g, ''));
          if (!offers || !(price > 0)) problems.push(`Product: offers.price=${offers?.['price']}`);
          if (offers?.['priceCurrency'] !== 'ILS') problems.push(`Product: priceCurrency=${offers?.['priceCurrency']}`);
          if (!ssrPrice) problems.push('Product с ценой, а в SSR-блоке нет «מחיר מבוקש:»');
        } else {
          if (priced) problems.push('Offer с полем price');
          if (ssrPrice) problems.push(`в SSR-блоке «מחיר מבוקש: ${ssrPrice}», а JSON-LD — Offer без цены`);
        }
        return { id, problems, priced };
      },
      (id, e) => ({ id, problems: [`ошибка запроса: ${e.message.split('\n')[0]}`], priced: false }),
    );

    const bad = rows.filter((r) => r.problems.length);
    expect(bad.map((r) => `${r.id}: ${r.problems.join('; ')}`), `нарушителей ${bad.length}/${rows.length}`).toEqual([]);
    // Покрытие обеих веток: если на проде нет объявлений с ценой или без — пометка, не падение.
    const withPrice = rows.filter((r) => r.priced).length;
    if (withPrice === 0 || withPrice === rows.length)
      test.info().annotations.push({ type: 'warning', description: `с ценой ${withPrice}/${rows.length} — одна из веток не проверена` });
  });
});
